const raw = String($input.first().json.text || '');
const offer = $('Make letter input').first().json.offer;
const master = $('Make letter input').first().json.master;
const problems = [];

// 1) Parse the model's answer (first "{" to last "}")
let L = {};
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
if (s >= 0 && e > s) {
  try { L = JSON.parse(raw.slice(s, e + 1)); } catch (err) { problems.push('answer is not valid JSON'); }
} else { problems.push('no JSON in answer'); }

// 2) Four paragraphs, plain text
let paras = ['p1', 'p2', 'p3', 'p4'].map(k => String(L[k] || '').replace(/\s+/g, ' ').trim());
paras.forEach((p, i) => { if (!p) problems.push('paragraph ' + (i + 1) + ' missing'); });
const full = paras.join(' ');

// 3) Length: one page = about 250-360 words in total
const words = full.split(/\s+/).filter(Boolean).length;
if (words < 250) problems.push('too short (' + words + ' words)');
if (words > 360) problems.push('too long (' + words + ' words)');

// 4) Numbers must come from the master CV or from the offer
//    (150k = 150,000 and number words such as "eight" are understood)
const allowed = master.map(r => r.text + ' ' + (r.dates || '')).join(' ') + ' ' + JSON.stringify(offer);
const withCommas = v => String(v).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const okNums = new Set((allowed.match(/\d[\d.,]*/g) || []).map(n => n.replace(/[.,]+$/, '')));
for (const m of allowed.matchAll(/(\d+(?:\.\d+)?)\s?k\b/gi)) {
  const v = Math.round(parseFloat(m[1]) * 1000);
  okNums.add(String(v)); okNums.add(withCommas(v));
}
const wordNums = { two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
const nums = (full.match(/\d[\d.,%]*/g) || []).map(n => n.replace(/[.,%]+$/, ''));
for (const w of full.toLowerCase().match(/\b[a-z]+\b/g) || []) if (wordNums[w]) nums.push(String(wordNums[w]));
const badNums = [...new Set(nums.filter(n => !okNums.has(n) && !allowed.includes(n)))];
if (badNums.length) problems.push('number not in master or offer: ' + badNums.join(', '));

// 4b) Every "month year" in the letter must exist in the master dates or in the offer
//     ("Jun-Aug 2026" counts as Jun 2026 and Aug 2026; "June" and "Jun" are the same)
const MON = 'jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec';
const dateRe = new RegExp('\\b(' + MON + ')[a-z]*\\.?(?:\\s*(?:-|–|to|and)\\s*(' + MON + ')[a-z]*\\.?)?\\s+(\\d{4})\\b', 'gi');
const monthKeys = text => {
  const out = new Set();
  for (const m of text.matchAll(dateRe)) {
    out.add(m[1].toLowerCase() + ' ' + m[3]);
    if (m[2]) out.add(m[2].toLowerCase() + ' ' + m[3]);
  }
  return out;
};
const okDates = monthKeys(allowed);
const badDates = [...monthKeys(full)].filter(k => !okDates.has(k));
if (badDates.length) problems.push('month/year not in master or offer: ' + badDates.join(', '));

// 5) Company must be named, no leftovers
const company = String(offer.company || '').trim();
if (company && !full.toLowerCase().includes(company.toLowerCase().split(/[ ,(]/)[0])) problems.push('company not mentioned');
if (/\[[^\]]*\]|\{\{|lorem|dear |sincerely/i.test(full)) problems.push('placeholder, greeting or sign-off inside a paragraph');

// 6) Style, tense and role checks
if (/currently[^.]{0,60}(summer school|exchange|programme|program)|(summer school|exchange)[^.]{0,60}currently/i.test(full)) problems.push('a past programme is described as current');
if ((full.match(/\b(additionally|furthermore|moreover)\b/gi) || []).length > 1) problems.push('too many connectors (additionally / furthermore / moreover)');
const allowedLow = allowed.toLowerCase();
for (const v of ['led', 'managed', 'headed', 'spearheaded', 'founded', 'directed', 'oversaw', 'supervised']) {
  const re = new RegExp('\\b' + v + '\\b', 'i');
  if (re.test(full) && !re.test(allowedLow)) problems.push('leadership claim not in master CV: ' + v);
}
if (/\b(shows|demonstrates|reflects|proves|illustrates)\b[^.]{0,40}\b(habit|ability|commitment|passion|drive|curiosity|skill)/i.test(full)) problems.push('interpretation of the candidate (shows / demonstrates a quality)');

// 6b) High-risk finance terms in the evidence paragraphs (2 and 3) must be written in the master CV itself
const masterLow = master.map(r => String(r.text || '')).join(' ').toLowerCase();
const evidence = (paras[1] + ' ' + paras[2]).toLowerCase();
for (const term of ['validation', 'validate', 'validating', 'stress test', 'stress-test', 'stress testing', 'inflation', 'structured product', 'pre-trade', 'compliance', 'audit']) {
  if (evidence.includes(term) && !masterLow.includes(term)) problems.push('claim not supported by the master CV: ' + term);
}

// 6c) A tool may be attached to a piece of work only if that item's own text names it.
//     Sentences about the toolkit itself (skills) are free.
const TOOLS = ['pandas', 'numpy', 'matplotlib', 'scikit-learn', 'sql', 'excel', 'vba', 'power bi', 'git', 'linux', 'latex', 'fastapi', 'react', 'docker', 'airflow', 'metabase', 'bloomberg', 'summit', 'python', 'pytorch', 'tensorflow', 'tableau', 'spark'];
const workLow = master.filter(r => r.section !== 'skill' && r.section !== 'fixed').map(r => String(r.text || '') + ' ' + String(r.role || '')).join(' ').toLowerCase();
const sentences = (paras[1] + ' ' + paras[2]).match(/[^.!?]+[.!?]*/g) || [];
for (const sen of sentences) {
  const low = sen.toLowerCase();
  if (/\b(toolkit|skills?|comfortable|familiar|proficient)\b|\bi (also )?(use|work)\b/.test(low)) continue;
  for (const t of TOOLS) {
    const re = new RegExp('(^|[^a-z])' + t.replace(/[-+.]/g, '\\$&') + '([^a-z]|$)');
    if (re.test(low) && !workLow.includes(t)) problems.push('tool attached to work that does not name it: ' + t);
  }
}
// 6d) What an experience gave the candidate is an interpretation, not a fact (coursework sentences are allowed)
if (full.split(/(?<=[.!?])\s+/).some(s => /\b(put|puts|gave|gives|taught|teaches|prepared|prepares|equipped|equips|showed)\s+me\b/i.test(s) && !/\b(course|courses|coursework|module|class|classes|degree|studies)\b/i.test(s))) problems.push('sentence about what an experience gave the candidate');

// 7) Slots for the Google Doc template
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const now = new Date();
const slots = {
  date: now.getDate() + ' ' + months[now.getMonth()] + ' ' + now.getFullYear(),
  company: company || 'Hiring Team',
  location: String(offer.location || ''),
  job_title: String(offer.job_title || ''),
  greeting: 'Dear Hiring Team,',
  p1: paras[0], p2: paras[1], p3: paras[2], p4: paras[3]
};
// an empty location line would leave a blank line: mark it for deletion (same trick as the CV)
if (!slots.location) slots.location = '§§DEL§§';

return [{ json: { letter_ok: problems.length === 0, problems, words, slots } }];

const doc = $input.first().json;
const slots = $('Validate letter').first().json.slots;
const documentId = $('Copy letter template').first().json.id;
const DEL = '§§DEL§§';


const content = (doc.body && doc.body.content) || [];
const endOfBody = content.length ? content[content.length - 1].endIndex : 0;

// Header (name and contact line) from the master profile, if one is known
const profile = $('Make letter input').first().json.profile || {};
const headerRepl = [];
const paraText = block => (block.paragraph.elements || []).map(el => (el.textRun ? el.textRun.content : '')).join('').replace(/\n$/, '').trim();
if (profile.name || profile.email || profile.phone || profile.linkedin) {
  const words = String(profile.name || '').trim().split(/\s+/).filter(Boolean);
  const last = words.length > 1 ? words.pop() : '';
  const first = words.join(' ');
  const cap = w => (w ? w.charAt(0).toUpperCase() + w.slice(1).toLowerCase() : w);
  const plainName = (first + ' ' + last.split('-').map(cap).join('-')).trim();
  const headerName = last ? first + ' ' + last.toUpperCase() : first.toUpperCase();
  const contact = [profile.email, profile.phone, profile.linkedin].filter(Boolean).join('  |  ');
  const doneTexts = new Set();
  for (const block of content) {
    if (!block.paragraph) continue;
    const t = paraText(block);
    if (!t || doneTexts.has(t)) continue;
    if (profile.name && /^alex\s+martin$/i.test(t)) { headerRepl.push([t, /MARTIN/.test(t) ? headerName : plainName]); doneTexts.add(t); }
    else if (contact && /@example\.com/i.test(t)) { headerRepl.push([t, contact]); doneTexts.add(t); }
  }
}

// 1) Paragraphs to delete: any paragraph holding a placeholder whose value is the marker
const toDelete = [];
const seen = new Set();
for (const block of content) {
  if (!block.paragraph) continue;
  const text = (block.paragraph.elements || []).map(el => (el.textRun ? el.textRun.content : '')).join('');
  const keys = [...text.matchAll(/\{\{(\w+)\}\}/g)].map(m => m[1]);
  keys.forEach(k => seen.add(k));
  if (keys.some(k => slots[k] === DEL || !(k in slots))) {   // unused or unknown placeholder: remove the paragraph
    // the last newline of the document can never be deleted
    toDelete.push({ start: block.startIndex, end: Math.min(block.endIndex, endOfBody - 1) });
  }
}
toDelete.sort((a, b) => b.start - a.start);   // from the end, so earlier indexes stay valid

// 2) Requests: delete the unused paragraphs first, then replace every other placeholder
const requests = toDelete.map(r => ({ deleteContentRange: { range: { startIndex: r.start, endIndex: r.end } } }));
for (const [key, value] of Object.entries(slots)) {
  if (value === DEL) continue;
  requests.push({ replaceAllText: { containsText: { text: '{{' + key + '}}', matchCase: true }, replaceText: String(value) } });
}

for (const [from, to] of headerRepl) requests.push({ replaceAllText: { containsText: { text: from, matchCase: true }, replaceText: to } });

// 3) Safety: placeholders in the document that have no value
const missing = [...seen].filter(k => !(k in slots));

return [{ json: {
  documentId,
  deleted: toDelete.length,
  replacements: requests.length - toDelete.length,
  missing,
  body: { requests }
} }];

const it = $input.first();
const bin = it.binary || {};
const key = Object.keys(bin)[0];
if (!key) return [{ json: { ok: false, error: 'Letter file missing' } }];
const buf = await this.helpers.getBinaryDataBuffer(0, key);
const company = String($('Make letter input').first().json.offer.company || 'Company').replace(/[^\p{L}\p{N}]+/gu, '_').replace(/^_+|_+$/g, '').slice(0, 40) || 'Company';
const kind = 'Cover_letter';
return [{ json: { ok: true, filename: kind + '_' + company + '.pdf', b64: buf.toString('base64') } }];
